"""Data files of the badges 1-9 scope (intro -> Luna), generated by tools/ (see DEV.md section 5). pkgutil also reads them from
inside the .apworld zip."""
import json
import pkgutil
from typing import Any


def load(name: str) -> Any:
    return json.loads(pkgutil.get_data(__name__, f"data/{name}.json").decode("utf-8"))


ROADBLOCKS: dict[str, Any] = load("roadblocks")
CHECKS: list[dict[str, Any]] = load("checks")["checks"]
ITEM_TABLE: dict[str, dict[str, Any]] = load("items")["items"]
_story = load("story")
STORY_IDS: dict[str, list[int]] = {"switches": _story["switches"], "variables": _story["variables"]}
